    main.style.display = hasTodos ? '' : 'none';
    footer.style.display = hasTodos ? '' : 'none';
    updateCount();
    updateToggleAll();
    updateClearCompleted();
  }

  function updateCount() {
    const active = document.querySelectorAll('.todo-list > li:not(.completed)').length;
